style.css:
@-moz-document domain("www.tumblr.com") {
/* HIDE ORIGINAL ICONS */
button[aria-label*="Text"] svg,
button[aria-label*="Photo"] svg,
button[aria-label*="Quote"] svg,
button[aria-label*="Link"] svg,
button[aria-label*="Chat"] svg,
button[aria-label*="Audio"] svg,
button[aria-label*="Video"] svg,
button[aria-label*="Text"] img,
button[aria-label*="Photo"] img,
button[aria-label*="Quote"] img,
button[aria-label*="Link"] img,
button[aria-label*="Chat"] img,
button[aria-label*="Audio"] img,
button[aria-label*="Video"] img {
    display: none !important;
}

/* BUTTON POSITIONING */
button[aria-label*="Text"],
button[aria-label*="Photo"],
button[aria-label*="Quote"],
button[aria-label*="Link"],
button[aria-label*="Chat"],
button[aria-label*="Audio"],
button[aria-label*="Video"] {
    position: relative !important;
}

/* NEW ICONS */
button[aria-label*="Text"]::after {
    content: "✧";
}

button[aria-label*="Photo"]::after {
    content: "▱";
}

button[aria-label*="Quote"]::after {
    content: "❧";
}

button[aria-label*="Link"]::after {
    content: "∞";
}

button[aria-label*="Chat"]::after {
    content: "☽";
}

button[aria-label*="Audio"]::after {
    content: "♬";
}

button[aria-label*="Video"]::after {
    content: "✴";
}

/* CENTRE AND ENLARGE NEW ICONS */
button[aria-label*="Text"]::after,
button[aria-label*="Photo"]::after,
button[aria-label*="Quote"]::after,
button[aria-label*="Link"]::after,
button[aria-label*="Chat"]::after,
button[aria-label*="Audio"]::after,
button[aria-label*="Video"]::after {
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    font-size: 36px !important;
    font-weight: normal !important;
    color: #c8b9dc !important;
    line-height: 1 !important;
    display: block !important;
    pointer-events: none !important;
}
}

/* PREVENT TEXT FROM OVERLAPPING ICONS */
button[aria-label*="Text"],
button[aria-label*="Photo"],
button[aria-label*="Quote"],
button[aria-label*="Link"],
button[aria-label*="Chat"],
button[aria-label*="Audio"],
button[aria-label*="Video"] {
    font-size: 0 !important;
}

/* KEEP NEW ICONS VISIBLE */
button[aria-label*="Text"]::after,
button[aria-label*="Photo"]::after,
button[aria-label*="Quote"]::after,
button[aria-label*="Link"]::after,
button[aria-label*="Chat"]::after,
button[aria-label*="Audio"]::after,
button[aria-label*="Video"]::after {
    font-size: 36px !important;
}


/* BUTTON LAYOUT */
button[aria-label*="Text"],
button[aria-label*="Photo"],
button[aria-label*="Quote"],
button[aria-label*="Link"],
button[aria-label*="Chat"],
button[aria-label*="Audio"],
button[aria-label*="Video"] {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 5px !important;
    font-size: 12px !important;
    position: relative !important;
}

/* ICON POSITION */
button[aria-label*="Text"]::after,
button[aria-label*="Photo"]::after,
button[aria-label*="Quote"]::after,
button[aria-label*="Link"]::after,
button[aria-label*="Chat"]::after,
button[aria-label*="Audio"]::after,
button[aria-label*="Video"]::after {
    position: static !important;
    transform: none !important;
    font-size: 36px !important;
    line-height: 1 !important;
    color: #c8b9dc !important;
    display: block !important;
}

/* KEEP LABELS BELOW ICONS */
button[aria-label*="Text"],
button[aria-label*="Photo"],
button[aria-label*="Quote"],
button[aria-label*="Link"],
button[aria-label*="Chat"],
button[aria-label*="Audio"],
button[aria-label*="Video"] {
    color: #bdb0cc !important;
}
